FRART=[('Les exigences avant les technologies','Partir du contexte', [('Décrire le parcours métier','Suivez une demande de sa création à sa validation, puis à son traitement et son reporting. Identifiez les acteurs, leurs droits et les éléments qui doivent rester traçables.'),('Formuler des exigences vérifiables','Précisez l’action, la charge attendue et le délai acceptable. Faites de même pour la reprise, les droits et la fraîcheur des rapports. Distinguez les volumes mesurés des hypothèses.'),('Comparer les options','Évaluez la maintenabilité, les compétences disponibles, le coût et les possibilités de récupération. Consignez les compromis et les conditions qui justifieraient une nouvelle décision.')]),('Des données opérationnelles aux rapports fiables','Des données traçables',[('Définir les indicateurs','Un chiffre de ventes peut représenter les commandes, les paiements ou les livraisons. Convenez de la définition, du fuseau horaire, des remboursements et du responsable de validation.'),('Préserver la traçabilité','Conservez les références sources et les métadonnées nécessaires pour expliquer les transformations, dans le respect des règles de conservation et de confidentialité.'),('Prévoir les exceptions','Vérifiez les doublons, les références et les totaux. Définissez le traitement des données tardives, les reprises et le responsable des anomalies. Une tâche terminée ne prouve pas la qualité du résultat.')]),('Rendre les déploiements fiables','Déployer avec méthode',[('Identifier la version','Reliez chaque déploiement à une révision source, un artefact et des changements de configuration. Une version doit être identifiable et reproductible.'),('Vérifier ce qui peut échouer','Choisissez des contrôles adaptés aux risques du changement : droits, compatibilité des migrations, transactions métier et comportement observable.'),('Préparer la reprise','Distinguez le retour à une version applicative de la restauration des données. Vérifiez la compatibilité et testez la procédure de récupération avant l’incident. Attribuez les responsabilités de décision et d’intervention.')])]

def build():
 for folder in ['assets','fr/assets']:
  (O/folder).mkdir(parents=True,exist_ok=True)
  for f in (R/'assets').iterdir():
   if f.is_file():shutil.copyfile(f,O/folder/f.name)
 (O/'.nojekyll').touch(); paths=[]
 for lang,t in T.items():
  pre='fr/' if lang=='fr' else ''; fr=lang=='fr'
  def link(p,label,cls=''):return f'<a class="{cls}" href="{u(pre+p)}">{label}</a>'
  def hero(label,title,desc):return f'<section class="page-hero wrap"><p class="eyebrow">{label}</p><h1>{title}</h1><p class="lede">{desc}</p></section>'
  def section(body,cls=''):return f'<section class="section wrap {cls}">{body}</section>'
  def cta():return section(f'<h2>{t["contact"]}</h2>{link("contact/",t["talk"],"solid")}','soft')
  def page(route,title,desc,body,redirect=None):
   path=pre+route;other=('' if fr else 'fr/')+(redirect if redirect is not None else route); canonical=HOST+u(pre+(redirect if redirect is not None else route))
