  diagram=f'<aside class="system-map" aria-label="{"Les couches du système" if fr else "System layers"}"><span class="eyebrow">ZAWATU / SYSTEM THINKING</span><div class="map-purpose">{purpose}<span>↗</span></div><p>{boundaries}</p><div class="map-layers"><span>{"Données" if fr else "Data"}</span><span>{"Logiciels" if fr else "Software"}</span><span>{"Plateforme" if fr else "Platform"}</span></div><p class="fine">{"Des décisions cohérentes, de la conception à l’exploitation." if fr else "Connected decisions, from design to operation."}</p></aside>'
  home=f'<section class="arch-hero wrap"><div><p class="eyebrow">{t["label"]}</p><h1>{t["hero"]}</h1><p class="lede">{t["intro"]}</p><div class="technical-actions">{link("contact/",t["talk"],"solid")}{link("zaf/","Explorer ZAF ↗" if fr else "Explore ZAF ↗","text-link")}</div></div>{diagram}</section><div class="scope-bar wrap"><span>{t["scope"]}</span><span class="scope-line"></span><span>EN / FR</span></div>'
