   if key in ['area','engagement']:
    opts=t['areas'] if key=='area' else t['engagements'];control=f'<select name="{key}">'+''.join(f'<option>{e(x)}</option>' for x in opts)+'</select>'
   elif key in ['details','outcome']:control=f'<textarea name="{key}" rows="4" required maxlength="3000"></textarea>'
   else:control=f'<input name="{key}" type="{"email" if key=="email" else "text"}" {"required" if key!="budget" else ""} maxlength="300" {"autocomplete=email" if key=="email" else "autocomplete=name" if key=="name" else ""}>'
